if REFERENCE_SECTION.strip() not in reference:
    marker = "## Live activity state\n"
    if marker not in reference:
        raise SystemExit("live Mission Control reference marker missing")
    write(
        "references/live-mission-control.md",
        reference.replace(marker, REFERENCE_SECTION + marker, 1),
    )

write("tests/test_visual_consistency.py", TEST_CONTENT)
